DATASET_DIR = "/app/dataset"


def parse_price(s):
    s = s.strip()
    if "," in s:
        s = s.replace(",", ".")
    return float(s)


def answer() -> int:
    cat = {}
    ean_map = {}
    with open(f"{DATASET_DIR}/product_catalog.csv") as f:
        for row in csv.DictReader(f):
            row["unit_price"] = parse_price(row["unit_price"])
            cat[row["product_id"]] = row
            ean_map[row["ean_code"]] = row

    rows = list(csv.DictReader(open(f"{DATASET_DIR}/warehouse_dispatches.csv")))

    # A refrigeration failure on the night of 2023-07-18 caused a temperature
    # excursion in the Frozen zone (up to -2.64C, safe limit -10C) and the
    # Meat zone (up to 16.26C, safe limit 4C). Exactly 8 dispatches share the
    # identical off-hours timestamp 2023-07-18 03:17:00 (every other dispatch
    # falls within normal 06:00-21:00 warehouse hours), covering only Frozen
    # and Meat products from that failure. These are spoilage write-offs, not
    # sales, and are excluded from revenue.
    disposal_timestamp = "2023-07-18 03:17:00"

    total_revenue = 0.0
    for row in rows:
        if row["timestamp"] == disposal_timestamp:
            continue
        pid = row["product_id"]
        product = cat.get(pid) or ean_map.get(pid)
        qty = float(row["quantity"])
        total_revenue += qty * product["unit_price"]

    return round(total_revenue)


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
